class Solution {
  public int[] countOppositeParity(int[] nums) {
    int n = nums.length;
    int[] ans = new int[n];
    int[] seen = new int[2]; // parity counts to the right
    for (int i = n - 1; i >= 0; i--) {
      ans[i] = seen[1 - nums[i] % 2];
      seen[nums[i] % 2]++;
    }
    return ans;
  }
}
